import{_ as t,h as n,i as a,c as i,v as o,p as d,x as l,m as r,e as s,S as h}from"./chunks/framework.Dvtg8yj2.js";const S=JSON.parse('{"title":"Function calling","description":"","frontmatter":{"title":"Function calling","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/function-calling.md","filePath":"llm/function-calling.md","lastUpdated":1788454257000}'),m={name:"llm/function-calling.md"};function p(u,e,_,f,A,E){const c=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="function-calling" tabindex="-1">Function calling <a class="header-anchor" href="#function-calling" aria-label="Permalink to &quot;Function calling&quot;">​</a></h1><div class="epigraph"><p>把工具写成带 JSON Schema 的函数声明，模型在该调用时产出结构化的名字与参数，而不是在散文里假装自己查过数据库。</p><footer>—— 对照 OpenAI 2023 年 function calling / 后续 tools 字段；Toolformer 则表明模型可以学会何时插入工具调用</footer></div><p>对话模型默认只会续写文本。产品要的却是查库存、跑 SQL、调日历——这些动作发生在模型权重之外。Function calling 把「可调用的副作用」收成一份工具清单：每条有名字、自然语言说明、以及参数的 JSON Schema。模型若决定调用，就不再只写 <code>content</code>，而是产出带 <code>tool_calls</code> 的助手消息；运行时执行真正的函数，把结果以 <code>role: tool</code> 写回，再让模型生成最终答复。它是协议加解码约定，不是新的注意力层。Schick 等人的 Toolformer 证明语言模型能在自监督里学会插入工具调用；OpenAI 兼容的 <code>tools</code> 字段则把这件事变成 HTTP 信封上的一等公民，见 <a href="/llm/openai-compat-api">OpenAI 兼容协议</a>。本篇写三次角色切换、参数如何落地、以及它与自由格式 <a href="/llm/react">ReAct</a> 的差别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无工具的助手只能用训练记忆回答。记忆会过时，也没有权限去碰用户的私有系统。若只靠提示「请按 <code>Action: search[...]</code> 的格式调用」，模型会漏写括号、发明不存在的工具名、把参数嵌进散文。下游用正则去抢救，失败率随工具数量与嵌套参数上升。需要一份机器可校验的契约：工具集合是显式的，参数类型是显式的，调用与观察在消息列表里有固定位置。</p><p>另一半问题是把「模型建议调用」和「副作用已发生」混为一谈。模型输出 <code>get_weather(city=&quot;北京&quot;)</code> 只是一段 token；真正的 HTTP 请求必须由宿主执行，并决定超时、鉴权、重试。协议若把这两步画成同一次生成，审计和权限都会乱。Function calling 的最小完备集因此是：声明、生成调用、执行、回填、再生成。缺任何一环，都不是完整的工具使用。</p><h3 id="信封里的三次角色切换" tabindex="-1">信封里的三次角色切换 <a class="header-anchor" href="#信封里的三次角色切换" aria-label="Permalink to &quot;信封里的三次角色切换&quot;">​</a></h3><p>一次成功的调用在 <code>messages</code> 里至少换三次说话人。用户（或系统）给出任务；助手给出 <code>tool_calls</code>（<code>id</code>、函数名、参数字符串）；工具角色按 <code>tool_call_id</code> 回填观察；助手再写给用户看的自然语言。并行调用时，一条助手消息里可以有多个 <code>id</code>，随后必须有同样数量的 tool 消息，否则下一轮前缀对不齐。<a href="/llm/chat-template">chat template</a> 要用与训练一致的分隔符渲染这三类角色；渲染错了，模型会把工具结果当成用户闲聊，或在该输出调用时输出散文。</p><p><span class="marginnote"><code>tool_choice</code> 是调度旋钮，不是模型能力。<code>none</code> 禁止调用，<code>required</code> 强迫至少一次，指定函数名则锁死目标。评测「会不会用工具」时必须声明这一字段；默认 <code>auto</code> 下模型可以合理选择不调用，不能据此判失败。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>请求侧把工具写成 JSON Schema：<code>name</code>、<code>description</code>、<code>parameters</code>（通常是 object，写清 <code>required</code> 与类型）。描述要写清副作用与单位，否则模型会用错时区或把用户 ID 填进查询字符串。服务端把这份清单经模板塞进系统前缀，使条件分布看见「当前会话允许哪些名字」。生成时，要么靠提示让模型自由写 JSON，要么用<a href="/llm/constrained-decoding">约束解码</a>把参数卡在 schema 上，见 <a href="/llm/json-schema-decode">JSON / 结构化输出</a>。后者能保证 <code>json.loads</code> 成功，不能保证参数在业务上合法——城市名拼对、主键存在，仍要工具自己校验。</p><p>执行侧按名字做白名单分发，禁止模型指定任意 URL 或 shell。超时与错误应写成工具观察，而不是让网关直接 500：模型需要看到「库存接口 503」，才能改口或换工具。回填后再次请求模型，<code>tool_calls</code> 那一轮助手消息必须原样保留在历史上，否则模型不知道自己做过什么。多轮工具循环要设步数上限与重复调用检测，避免查询参数微扰造成的死循环。</p>',12)),(a(),d(h,null,{default:l(()=>[s(c,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E6%B6%88%E6%81%AF%22%5D%20--%3E%20M%5B%22%E6%A8%A1%E5%9E%8B%EF%BC%9Acontent%20%E6%88%96%20tool_calls%22%5D%0A%20%20M%20--%3E%7C%E7%BA%AF%E6%96%87%E6%9C%AC%7C%20A%5B%22%E7%9B%B4%E6%8E%A5%E7%AD%94%E5%A4%8D%22%5D%0A%20%20M%20--%3E%7C%E8%B0%83%E7%94%A8%7C%20X%5B%22%E5%AE%BF%E4%B8%BB%E6%8C%89%E7%99%BD%E5%90%8D%E5%8D%95%E6%89%A7%E8%A1%8C%22%5D%0A%20%20X%20--%3E%20T%5B%22role%3A%20tool%20%E8%A7%82%E5%AF%9F%22%5D%0A%20%20T%20--%3E%20M%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="参数-json-与工具选择" tabindex="-1">参数 JSON 与工具选择 <a class="header-anchor" href="#参数-json-与工具选择" aria-label="Permalink to &quot;参数 JSON 与工具选择&quot;">​</a></h3><p>参数几乎总是一个 JSON 对象字符串。键名必须与 schema 一致；模型常把 <code>user_id</code> 写成 <code>userId</code>，或把数字写成带逗号的字符串。约束解码可以钉住键集合，枚举字段可以钉住合法取值。工具选择则是另一层：相关工具太多时，描述会挤占上下文，模型更容易张冠李戴。工程上按意图路由、按用户权限裁剪可见工具，比把一百个函数一次性塞进 schema 更有效。<a href="/llm/mcp">MCP</a> 把「有哪些工具」从静态请求字段变成运行时发现，但调用语义仍然是这一套名字加参数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模型并没有获得新的作用子。训练（或指令数据）让它在「该用工具」的前缀上把概率质量放到调用格式上；推理时格式被模板与可选文法进一步收窄。调用是否发生，取决于描述、当前对话、以及 <code>tool_choice</code>。并行调用能把互相独立的只读查询合成一轮，降低往返；有数据依赖的调用（先搜 ID 再取详情）必须串行，硬并行只会得到空参数。观察写回之后，模型是在 <em>新的条件前缀</em> 上继续生成，不是在第一次前向里「想起」了结果。</p><p>失败模式集中在三类。名称幻觉：产出不在清单里的函数，宿主应拒绝并回填错误，而不是静默丢弃。参数幻觉：类型对、值假，只能靠工具或下游校验器。过调：明明可以靠已有上下文回答，仍调用搜索，既慢又把噪声文档读进下一轮。这三类都不会被「JSON 合法」消除。与 <a href="/llm/react">ReAct</a> 相比，function calling 把动作从自由文本槽位收成协议字段，便于鉴权与日志；代价是必须维护 schema 与模板，换模型时要重新对齐工具数据。</p><p><span class="marginnote">把 logits 处理器接到 <code>arguments</code> 上，保证的是括号与类型，不是副作用安全。<code>delete_user</code> 的 schema 再严格，一旦宿主真的执行，删除就会发生。权限属于执行层，不要指望 schema 替你做授权。</span></p><h3 id="并行调用与失败回填" tabindex="-1">并行调用与失败回填 <a class="header-anchor" href="#并行调用与失败回填" aria-label="Permalink to &quot;并行调用与失败回填&quot;">​</a></h3><p>并行时每个调用要有稳定 <code>id</code>，观察按 id 对齐，不能按数组下标在重试后错位。部分失败应逐条回填：一条超时、一条成功，模型才能决定是重试还是带着残缺答案继续。不要把整批调用折叠成一句「工具失败了」——信息量不够，下一轮往往会重复同一批调用。流式场景里，<code>tool_calls</code> 的参数字符串是逐步拼出来的，客户端应等调用帧结束再执行，避免对半截 JSON 发请求。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Function calling 不规定检索、浏览器或代码沙箱怎么实现；那些是工具后端。<a href="/llm/hybrid-retrieval">混合检索</a> 可以是其中一个函数，但协议不知情。它也不替代多步策略：一次调用不够时，循环是宿主的事，模型只看到消息列表。把循环做成 <a href="/llm/react">ReAct</a> 还是先写计划再执行，见 <a href="/llm/plan-vs-react">规划 vs 反应式循环</a>。</p><p>不要在系统提示里再手写一套与 schema 冲突的参数说明。不要让模型生成可执行代码当作「通用函数调用」，除非沙箱与资源限制已经单独设计。评测应分开报告：格式合法率、参数校验通过率、任务成功率。只报成功率会把「模型会写 JSON」和「工具真的办成了事」混在一起。兼容层若声称支持 <code>tools</code> 却在服务端丢掉该字段，表现为偶发不调用，根因在信封而不是权重。</p><p><span class="marginnote">出处以 OpenAI API 的 tools / tool_choice 说明、Hugging Face chat template 里的 tool 角色、以及 Schick et al., <em>Toolformer: Language Models Can Teach Themselves to Use Tools</em>, NeurIPS 2023 为准。不要给「某家闭源模型内部的工具头」编造架构论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Function calling 是工具声明、结构化调用、宿主执行、观察回填的协议循环，不是新参数。</li><li>消息角色必须按 assistant / tool 对齐；模板与训练格式不一致会表现为拒用工具或把观察当闲聊。</li><li>Schema 与约束解码保证参数可解析，不保证值真实、不保证副作用安全。</li><li><code>tool_choice</code>、可见工具集合、步数上限属于调度，应写进评测条件。</li><li>并行调用按 id 回填；部分失败不要折叠成一句空错误。</li><li>与自由格式 ReAct 相比，协议字段便于鉴权，但要维护 schema 与兼容层。</li><li>出处：OpenAI API 参考（function calling / tools）；Schick et al., <em>Toolformer</em>, NeurIPS 2023。</li></ul>',14))])}const T=t(m,[["render",p]]);export{S as __pageData,T as default};
